    create table appointments (
        appointment_date_time timestamp(6) not null,
        created_at timestamp(6) not null,
        doctor_id bigint not null,
        id bigint generated by default as identity,
        patient_id bigint not null,
        updated_at timestamp(6),
        notes TEXT,
        reason TEXT,
        status varchar(255) not null check ((status in ('PENDING','WAITING','IN_CONSULTATION','COMPLETED','CANCELLED','NO_SHOW'))),
        primary key (id)
    );

    create table bill_line_items (
        quantity integer not null,
        total_price numeric(10,2) not null,
        unit_price numeric(10,2) not null,
        bill_id bigint not null,
        created_at timestamp(6) not null,
        id bigint generated by default as identity,
        source_reference_id bigint,
        description varchar(255) not null,
        source varchar(255) not null check ((source in ('CONSULTATION','DRUG_DISPENSE','LAB','MANUAL'))),
        primary key (id),
        constraint uq_line_item_source unique (source, source_reference_id)
    );

    create table bills (
        appointment_id bigint,
        created_at timestamp(6) not null,
        id bigint generated by default as identity,
        patient_id bigint not null,
        updated_at timestamp(6),
        cancel_reason varchar(255),
        status varchar(255) not null check ((status in ('OPEN','PARTIALLY_PAID','PAID','CANCELLED'))),
        primary key (id)
    );

    create table doctors (
        is_available boolean,
        created_by_id bigint,
        created_on timestamp(6),
        id bigint generated by default as identity,
        speciality_id bigint,
        user_id bigint not null,
        primary key (id)
    );

    create table drugs (
        cost numeric(10,2),
        milligrams integer,
        quantity integer not null,
        id bigint generated by default as identity,
        manufacturer_id bigint,
        category varchar(255),
        name varchar(255) not null,
        primary key (id)
    );

    create table patients (
        date_of_birth date not null,
        created_at timestamp(6) not null,
        id bigint generated by default as identity,
        updated_at timestamp(6),
        user_id bigint not null unique,
        address varchar(255) not null,
        allergies TEXT,
        emergency_contact_name varchar(255),
        emergency_contact_phone varchar(255),
        gender varchar(255) check ((gender in ('MALE','FEMALE','OTHER'))),
        phone_number varchar(255) not null,
        primary key (id)
    );

    create table payments (
        amount numeric(10,2) not null,
        bill_id bigint not null,
        id bigint generated by default as identity,
        paid_at timestamp(6) not null,
        recorded_by_user_id bigint not null,
        method varchar(255) not null check ((method in ('CASH','MPESA','CARD','INSURANCE'))),
        reference varchar(255),
        primary key (id)
    );

    create table prescriptions (
        quantity integer not null,
        appointment_id bigint not null,
        created_on timestamp(6) not null,
        doctor_id bigint not null,
        drug_id bigint not null,
        id bigint generated by default as identity,
        dossage varchar(255) not null,
        duration varchar(255) not null,
        notes varchar(255),
        primary key (id)
    );

    create table users (
        enabled boolean not null,
        created_at timestamp(6) not null,
        id bigint generated by default as identity,
        updated_at timestamp(6),
        username varchar(50) not null unique,
        email varchar(255) not null unique,
        first_name varchar(255) not null,
        last_name varchar(255) not null,
        password varchar(255) not null,
        role varchar(255) not null check ((role in ('ROLE_ADMIN','ROLE_DOCTOR','ROLE_RECEPTIONIST','ROLE_PATIENT'))),
        primary key (id)
    );

